CREATE PROCEDURE [CDN].[POS_EksportRodzajeCen]
	@rowVersion bigint,
	@pointOfSaleId int
AS
BEGIN
	SET NOCOUNT ON;
	declare @dbts bigint = cast(@@DBTS as bigint)
	
	select
		@dbts as [@RowVersion], (
		select CenaLP as [@Id], case when archiwalny = 0 then 'true' else 'false' end as [@IsAvailable],'true' as [@IsForAllCustomers] from CDN.POS_TCNDoEksportu(@pointOfSaleId)
	for xml path('PriceType'), type)
	for xml path('PriceTypes')
	SET NOCOUNT OFF;	
END
